def toPIL16(self, filename=None):
    if not Image:
        raise RuntimeError('PIL is not installed !!! ')
    if filename:
        self.read(filename)
    if self.pilimage is not None:
        return self.pilimage
    size = self.data.shape[:2][::-1]
    typmap = {'float32': 'F', 'int32': 'F;32S', 'uint32': 'F;32', 'int16': 'F;16S', 'uint16': 'F;16', 'int8': 'F;8S', 'uint8': 'F;8'}
    if self.data.dtype.name in typmap:
        mode2 = typmap[self.data.dtype.name]
        mode1 = mode2[0]
    else:
        raise Exception('Unknown numpy type ' + str(self.data.dtype.type))
    dats = self.data.tostring()
    self.pilimage = Image.frombuffer(mode1, size, dats, 'raw', mode2, 0, 1)
    return self.pilimage

def _processMessage(self, msg):
    res = None
    wspaces = msg.count(' ')
    qmarks = msg.count('?')
    tokens = msg.split()
    if wspaces > 1 and qmarks > 0 or wspaces > 2 or qmarks > 1:
        res = 'ERROR: Cannot parse this command\n'
    elif qmarks:
        if tokens[0] == '*IDN?':
            res = IDN + '\n'
        elif tokens[0] == 'PWR?':
            pin = int(tokens[1])
            if pin < 0 or pin > 7:
                res = 'ERROR: Out of range pin number\n'
            else:
                ans = self._i2crcv >> pin & MASK
                res = str(ans) + '\n'
        else:
            res = 'ERROR: Cannot parse this command\n'
    elif wspaces:
        pin = int(tokens[1])
        val = int(tokens[2])
        if tokens[0] == 'PWR':
            if pin < 0 or pin > 7:
                res = 'ERROR: Out of range pin number\n'
            else:
                self._i2crcv = self._i2crcv & ~(1 << pin) | val << pin & 1 << pin
                res = '\n'
        elif tokens[0] == 'WMEM':
            res = '\n'
        elif tokens[0] == 'RMEM':
            res = '\n'
        else:
            res = 'ERROR: Cannot parse this command\n'
    else:
        res = 'ERROR: Cannot parse this command\n'
    if res is not None:
        self._output_buf += res

