def __init__(self):
    cls = self.__class__
    if cls in Visitor._visitor_functions_cache:
        (enter_fns, visit_fns, leave_fns, visit_class_names) = Visitor._visitor_functions_cache[cls]
    else:
        enter_fns = {}
        enter_prefix = 'Enter'
        enter_len = len(enter_prefix)
        visit_fns = {}
        visit_prefix = 'Visit'
        visit_len = len(visit_prefix)
        leave_fns = {}
        leave_prefix = 'Leave'
        leave_len = len(leave_prefix)
        for attrib in dir(cls):
            if attrib.startswith(enter_prefix):
                enter_fns[attrib[enter_len:]] = getattr(cls, attrib)
            elif attrib.startswith(visit_prefix):
                visit_fns[attrib[visit_len:]] = getattr(cls, attrib)
            elif attrib.startswith(leave_prefix):
                leave_fns[attrib[leave_len:]] = getattr(cls, attrib)
        ancestors = _GetAncestorMap()
        visit_class_names = set()
        visit_all = cls.Enter != Visitor.Enter or cls.Visit != Visitor.Visit or cls.Leave != Visitor.Leave
        for node in set(enter_fns) | set(visit_fns) | set(leave_fns):
            if node in ancestors:
                visit_class_names.update(ancestors[node])
            elif node:
                raise AssertionError('Visiting an unknown non-empty node: %s' % node)
        if visit_all:
            visit_class_names = ALL_NODE_NAMES
        Visitor._visitor_functions_cache[cls] = (enter_fns, visit_fns, leave_fns, visit_class_names)
    self.enter_functions = enter_fns
    self.visit_functions = visit_fns
    self.leave_functions = leave_fns
    self.visit_class_names = visit_class_names

def apply_method(self, r, **attr):
    if r.representation != 'pdf':
        r.error(415, current.ERROR.BAD_FORMAT)
    if not r.record or r.http != 'GET':
        r.error(400, current.ERROR.BAD_REQUEST)
    T = current.T
    invoice_no = r.record.invoice_no if r.record and 'invoice_no' in r.record else 'invoice'
    response = current.response
    response.headers['Content-Disposition'] = f'attachment; filename={invoice_no}.pdf'
    from s3.s3export import S3Exporter
    exporter = S3Exporter().pdf
    return exporter(r.resource, request=r, method='read', pdf_title=T('Invoice'), pdf_header=self.invoice_header, pdf_callback=self.invoice, pdf_footer=self.invoice_footer, pdf_hide_comments=True, pdf_header_padding=12, pdf_orientation='Portrait', pdf_table_autogrow='B', **attr)

def set_up(self):
    self.language_code = django_settings.LANGUAGE_CODE
    if '--run-all-languages' in sys.argv:
        pass
    if self.language_code in {'en', 'fr', 'he'}:
        pass
    elif self.language_code in {'de', 'es', 'pt', 'it', 'nl', 'sv', 'ko', 'fi'}:
        if not self.language_code == tests_settings.RANDOM_LANGUAGE_CODE_CHOICE:
            self.skipTest(reason='Skipped test - language code skipped.')
            return
    else:
        raise NotImplementedError()
    self.all_language_codes = [language_code for (language_code, language_name) in django_settings.LANGUAGES]
    self.all_other_language_codes = [language_code for (language_code, language_name) in django_settings.LANGUAGES if not language_code == self.language_code]
    self.http_host = '{language_code}.{domain}'.format(language_code=self.language_code, domain=self.site.domain)
    self.full_http_host = 'https://{http_host}/'.format(http_host=self.http_host)
    self.all_other_full_http_hosts = ['https://{language_code}.{domain}/'.format(language_code=language_code, domain=self.site.domain) for language_code in self.all_other_language_codes]
    self.client = self.client_class(HTTP_HOST=self.http_host)

def __init__(self, spectrogram, ratio=0.5, max_bins=3, diff_frames=None):
    from spectrogram import Spectrogram
    if isinstance(spectrogram, Spectrogram):
        self.s = spectrogram
    else:
        self.s = Spectrogram(spectrogram)
    if diff_frames is None:
        sample = np.argmax(self.s.window > ratio)
        diff_samples = self.s.window.size / 2 - sample
        diff_frames = int(round(diff_samples / self.s.hop_size))
        if diff_frames < 1:
            diff_frames = 1
    if diff_frames < 1:
        raise ValueError('number of diff_frames must be >= 1')
    self.diff_frames = diff_frames
    self.max_bins = max_bins

def datetime_to_pretty_str(date):
    if date is None:
        date = datetime_null()
    return date.strftime('%A %d %B %Y %H:%M (UTC)')

def get_formated_values(i, input_values):
    result = dict(zip(i.input_value_map.keys(), input_values))
    for (key, input_type) in i.input_type_map.items():
        if input_type == 'date':
            value = result[key]
            try:
                result[key] = datetime.strptime(value, '%Y-%m-%d').date() if value else value
            except ValueError:
                pass
    return result

