def _get_event_ids_for_partial_state_join(join_event: EventBase, prev_state_ids: StateMap[str]) -> Collection[str]:
    state_event_ids = {event_id for ((event_type, state_key), event_id) in prev_state_ids.items() if event_type != EventTypes.Member}
    current_membership_event_id = prev_state_ids.get((EventTypes.Member, join_event.state_key))
    if current_membership_event_id is not None:
        state_event_ids.add(current_membership_event_id)
    for ((event_type, state_key), event_id) in prev_state_ids.items():
        if event_type == EventTypes.Invite or event_type == EventTypes.Kick:
            state_event_ids.add(event_id)
    return state_event_ids

def _build_dict(self):
    data = {}
    data['message_type'] = NotificationType.type_names[self._type]
    data['message_data'] = {}
    data['message_data']['event_key'] = self.event.key_name
    data['message_data']['event_name'] = self.event.name
    data['message_data']['match_key'] = self.match.key_name
    data['message_data']['team_keys'] = self.match.team_key_names
    if self.match.time:
        data['message_data']['scheduled_time'] = calendar.timegm(self.match.time.utctimetuple())
        predicted_time = self.match.time + timedelta(minutes=10)
        data['message_data']['predicted_time'] = calendar.timegm(predicted_time.utctimetuple())
    else:
        data['message_data']['scheduled_time'] = None
        data['message_data']['predicted_time'] = None
    current_webcasts = self.event.current_webcasts
    WebcastOnlineHelper.add_online_status(current_webcasts)
    online_webcasts = filter(lambda x: x.get('status', '') != 'offline', current_webcasts if current_webcasts else [])
    if online_webcasts:
        data['message_data']['webcast'] = online_webcasts[0]
    else:
        data['message_data']['webcast'] = None
    return data

def isSpreadSheetCell(self, obj, startFromTable=False):
    cell = obj
    if not startFromTable:
        obj = obj.parent
    try:
        table = obj.queryTable()
    except:
        return False
    else:
        return table.nRows in [65536, 1048576]

def do_main():
    from xpra.os_util import SIGNAMES
    from xpra.scripts.main import InitExit, InitInfo
    from xpra.gtk_common.quit import gtk_main_quit_on_fatal_exceptions_enable
    gtk_main_quit_on_fatal_exceptions_enable()
    from xpra.platform.gui import ready as gui_ready
    gui_init()
    try:
        from xpra.scripts.parsing import parse_cmdline, fixup_debug_option
        (options, args) = parse_cmdline(sys.argv)
        debug = fixup_debug_option(options.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
    except InitInfo as e:
        print(str(e))
        return 0
    except InitExit as e:
        return e.status
    except Exception:
        exception_dialog('Error parsing command line')
        return 1
    from xpra.scripts import config
    config.debug = log.debug
    try:
        app = ApplicationWindow()

        def app_signal(signum, _frame):
            print('')
            log('got signal %s' % SIGNAMES.get(signum, signum))

            def show_signal():
                app.show()
                app.client.cleanup()
                glib.timeout_add(1000, app.set_info_text, 'got signal %s' % SIGNAMES.get(signum, signum))
                glib.timeout_add(1000, app.set_info_color, True)
            glib.idle_add(show_signal)
        if sys.version_info[0] < 3:
            signal.signal(signal.SIGINT, app_signal)
        signal.signal(signal.SIGTERM, app_signal)
        has_file = len(args) == 1
        if has_file:
            app.update_options_from_file(args[0])
            configure_network(app.config)
        debug = fixup_debug_option(app.config.debug)
        if debug:
            for x in debug.split(','):
                enable_debug_for(x)
        app.create_window_with_config()
    except Exception:
        exception_dialog('Error creating launcher form')
        return 1
    try:
        if app.config.autoconnect:
            glib.idle_add(app.do_connect)
        if not has_file:
            app.reset_errors()
        gui_ready()
        if not app.config.autoconnect or app.config.debug:
            if OSX:

                def force_show():
                    from xpra.platform.darwin.gui import enable_focus_workaround, disable_focus_workaround
                    enable_focus_workaround()
                    app.show()
                    glib.timeout_add(500, disable_focus_workaround)
                app.__osx_open_signal = False

                def do_open_file(filename):
                    log.info('do_open_file(%s)', filename)
                    app.update_options_from_file(filename)
                    configure_network(app.config)
                    app.update_gui_from_config()
                    if app.config.autoconnect:
                        app.__osx_open_signal = True
                        glib.idle_add(app.do_connect)
                    else:
                        force_show()

                def open_file(_, filename):
                    log.info('open_file(%s)', filename)
                    glib.idle_add(do_open_file, filename)
                from xpra.platform.darwin.gui import get_OSXApplication, register_URL_handler
                register_URL_handler(open_URL)
                try:
                    get_OSXApplication().connect('NSApplicationOpenFile', open_file)
                except Exception as e:
                    log.error('Error: cannot handle file associations:')
                    log.error(' %s', e)

                def may_show():
                    log('may_show() osx open signal=%s', app.__osx_open_signal)
                    if not app.__osx_open_signal:
                        force_show()
                glib.timeout_add(500, may_show)
            else:
                app.show()
        app.run()
    except KeyboardInterrupt:
        pass
    return 0

def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                response = py.builtin.open(tryfn)
                if response is None:
                    py.test.fail('failed to retrieve %r in %s:%d' % (tryfn, path.basename, lineno + 1))
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d' % (tryfn, path.basename, lineno + 1))
            else:
                pass

def _retrieve(self, url):
    import codecs
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if info_dict.has_key('Content-Type'):
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                potential_encode = ct_line[csi+9:]
                try:
                    codecs.lookup(potential_encode)
                    encode = potential_encode
                except LookupError:
                    pass
        uopener.close()
        self.urlOpener.close()
    except IOError, e:
        raise IMDbDataAccessError, {'errcode': e.errno,
                                    'errmsg': str(e.strerror),
                                    'url': url,
                                    'proxy': self.get_proxy()}
    return unicode(content, encode, 'replace')

def config_init(prompt=True):
    config_path = os.getcwd() + '/.wandb'
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        tmp_path = config_path.replace('.wandb', '.wandb.tmp')
        if os.path.isfile(config_path):
            os.rename(config_path, tmp_path)
        os.mkdir(config_path)
        if os.path.isfile(tmp_path):
            os.rename(tmp_path, tmp_path.replace('.wandb.tmp', '.wandb/config'))
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
