def apply_change_to_nodes(self, nodes, text, pos):
    try:
        nodes.remove(None)
    except:
        pass
    sorted_nodes = sorted(nodes, key=lambda node: node.priority)
    for node in sorted_nodes:
        result = self.change_node(node, text, pos)
        if result:
            return
    if sorted_nodes and sorted_nodes[0].matches(text):
        current_node = sorted_nodes[0]
        current_node.change_text(current_node.symbol.name[:pos] + text + current_node.symbol.name[pos:])
        return
    new_node = TextNode(Terminal(text), -1, [], pos)
    new_node.regex = self.getPL().regex(text)
    new_node.priority = self.getPL().priority(text)
    new_node.lookup = self.getPL().name(text)
    sorted_nodes[0].parent.insert_after_node(sorted_nodes[0], new_node)

def run(self):
    if not Screenshot().have_pil():
        log.warning('Python Image Library is not installed, screenshots are disabled')
        return False
    img_counter = 0
    img_last = None
    while self.do_run:
        time.sleep(SHOT_DELAY)
        try:
            img_current = Screenshot().take()
        except IOError as e:
            log.error('Cannot take screenshot: %s', e)
            continue
        if img_last:
            if Screenshot().equal(img_last, img_current, SKIP_AREA):
                continue
        img_counter += 1
        img_last = img_current
    return True

