        self._pipette_offset = cur_pt

def format_courserun_for_dashboard(course_run, status_for_user, certificate=None, position=1):
    if course_run is None:
        return
    formatted_run = {'id': course_run.id, 'course_id': course_run.edx_course_key, 'title': course_run.title, 'status': status_for_user, 'position': position, 'course_start_date': course_run.start_date, 'course_end_date': course_run.end_date, 'fuzzy_start_date': course_run.fuzzy_start_date}
    extra_fields = CourseFormatConditionalFields.get_assoc_field(status_for_user)
    for extra_field in extra_fields:
        formatted_run[extra_field['format_field']] = getattr(course_run, extra_field['course_run_field'])
    if status_for_user == CourseStatus.PASSED:
        if certificate is not None:
            formatted_run['grade'] = certificate.grade
            formatted_run['certificate_url'] = certificate.download_url
        else:
            log.error('A valid certificate was expected')
    if status_for_user == CourseStatus.CURRENTLY_ENROLLED:
        current_grade = get_current_grade(course_run)
        formatted_run['current_grade'] = current_grade
    if status_for_user == CourseStatus.OFFERED or status_for_user == CourseStatus.CAN_UPGRADE:
        try:
            course_price = CoursePrice.objects.get(course_run=course_run, is_valid=True)
            formatted_run['price'] = course_price.price
        except CoursePrice.DoesNotExist:
            pass
    return formatted_run

def get_distribution_version():
    distribution_version = None
    if platform.system() == 'Linux':
        try:
            distribution_version = platform.linux_distribution()[1]
            if not distribution_version and os.path.isfile('/etc/system-release'):
                distribution_version = platform.linux_distribution(supported_dists=['system'])[1]
        except Exception:
            distribution_version = platform.dist()[1]
    return distribution_version

def get_model_object(self, name=None):
    if not name:
        name = self.name
    if not name:
        raise ValueError, 'AnswerBlock.name field need to be set to a non-null/empty value'
    student_id = self.scope_ids.anonymous_user_id
    answer_data, created = Answer.objects.get_or_create(
        student_id=student_id,
        name=name
    )
    return answer_data

def get_draft_validation_errors(draft_json, lot, framework_id=0, slug=None, required=None):
    if not slug and (not framework_id):
        raise Exception('Validation requires either framework_id or slug')
    if not slug:
        if framework_id == 1:
            slug = 'g-cloud-6'
        else:
            slug = 'g-cloud-7'
    errs = get_validation_errors('services-{0}-{1}'.format(slug, lot.lower()), draft_json, enforce_required=False, required_fields=required)
    return errs

