async def get_backup_details(request):
    backup_id = request.match_info.get('backup_id', None)
    if not backup_id:
        raise web.HTTPBadRequest(reason='Backup id is required')
    else:
        try:
            backup_id = int(backup_id)
        except ValueError:
            raise web.HTTPBadRequest(reason='Invalid backup id')
    try:
        Backup.get_backup_details.return_value = {'date': '2017-08-30 04:05:10.382', 'status': 'running'}
    except Backup.DoesNotExist:
        raise web.HTTPNotFound(reason='Backup with {} does not exist'.format(backup_id))
    _resp = Backup.get_backup_details(id=backup_id)
    _resp['id'] = backup_id
    return web.json_response(_resp)

def deserialize(cls, val):
    if isinstance(val, int):
        return val
    if '(' in val and ')' in val:
        return cls.process_macro_keycode(val)
    if '(' not in val and val in cls.qmk_id_to_keycode:
        return cls.qmk_id_to_keycode[val].code
    return 0

def compare_ode_sol(sol1, sol2, func, *args):
    from sympy.core.basic import C, S
    if sol1 == sol2:
        return 0
    if isinstance(sol1, list) or isinstance(sol1, tuple):
        sol1len = sum([len(str(i)) for i in sol1])
        sol1 = sorted(sol1, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol1) - 1]
    else:
        sol1len = len(str(sol1))
    if isinstance(sol2, list) or isinstance(sol2, tuple):
        sol2len = sum([len(str(i)) for i in sol2])
        sol2 = sorted(sol2, cmp=lambda x, y: compare_ode_sol(x, y, func, *args))[len(sol2) - 1]
    else:
        sol2len = len(str(sol2))
    intcmp = int(sol1.has(C.Integral)) - int(sol2.has(C.Integral))
    if intcmp:
        return intcmp
    sol1s = 0
    sol2s = 0
    if sol1.lhs == func and (not sol1.rhs.has(func)) or (sol1.rhs == func and (not sol1.lhs.has(func))):
        sol1s = 1
    if sol2.lhs == func and (not sol2.rhs.has(func)) or (sol2.rhs == func and (not sol2.lhs.has(func))):
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    try:
        sol1sol = solve(sol1, func)
        if sol1sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol1s = 1
    try:
        sol2sol = solve(sol2, func)
        if sol2sol == []:
            raise NotImplementedError
    except NotImplementedError:
        pass
    else:
        sol2s = 1
    if sol2s - sol1s:
        return sol2s - sol1s
    return cmp(sol1len, sol2len)

def reload_graphs(*updates):
    valid_hostnames = {'techerror.support', 'serveradmin.admin'}
    for (hostname, _) in updates:
        if hostname not in valid_hostnames:
            raise ValueError(f'Invalid hostname: {hostname}')
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect(settings.SERVERMONITOR_SERVER)
        s.sendall('HOSTNAME==serveradmin.admin\n')
        for (hostname, graphs) in updates:
            for graph in graphs:
                (graph_name, period) = split_graph_name(graph)
                if not period:
                    period = ''
                s.sendall('RELOAD=={graph}##{period}##{hostname}##\n'.format(graph=graph_name, period=period, hostname=hostname))
        s.sendall('DONE\n')
        fileobj = s.makefile()
        return ['SUCCESS' == line.strip() for line in fileobj.readlines()]
    except socket.error:
        return [False] * sum((len(graphs) for (_host, graphs) in updates))

def read_files(self):
    bdeps = dict()
    bprov = dict()
    for fname in self.files:
        bin = [x for x in fname.split('@') if x.startswith('binary-')][0][7:]
        if bin not in bdeps:
            bdeps[bin] = dict()
            bprov[bin] = dict()
        try:
            reader = gzip.GzipFile(fname)
        except:
            print('Failed to read file %s' % fname)
            raise Exception()
            continue
        for line in reader.readlines():
            words = line.strip().split(':', 1)
            if words[0] == 'Package':
                pkgname = words[1].strip().rstrip()
                self.pkgnames.add(pkgname)
            elif words[0] == 'Depends':
                bdeps[bin][pkgname] = []
                for dep in words[1].split(','):
                    raw_dep = re.sub('\\(.*\\)', '', dep)
                    raw_dep = raw_dep.rstrip().strip()
                    bdeps[bin][pkgname].append(raw_dep)
            elif words[0] == 'Provides':
                for pkg in words[1].split(','):
                    dname = pkg.rstrip().strip()
                    if dname not in bprov[bin]:
                        bprov[bin][dname] = set()
                    bprov[bin][dname].add(pkgname)
    self.deps['global'] = dict()
    self.provides['global'] = dict()
    for bin in bdeps:
        self.deps[bin] = dict()
        self.provides[bin] = dict()
    for pkgname in self.pkgnames:
        pset = set()
        for bin in bdeps:
            if pkgname not in bdeps[bin]:
                bdeps[bin][pkgname] = []
            pset.add(tuple(bdeps[bin][pkgname]))
        if len(pset) == 1:
            self.deps['global'][pkgname] = pset.pop()
        else:
            for bin in bdeps:
                self.deps[bin][pkgname] = bdeps[bin][pkgname]
    provided = set()
    for bin in bprov:
        for prov in bprov[bin]:
            provided.add(prov)
    for prov in provided:
        prset = set()
        for bin in bprov:
            if prov not in bprov[bin]:
                continue
            prset.add(tuple(bprov[bin].get(prov, ())))
        if len(prset) == 1:
            self.provides['global'][prov] = prset.pop()
        else:
            for bin in bprov:
                self.provides[bin][prov] = bprov[bin].get(prov, ())
    self.save_state()

def ProcessTimelineEvent(self, timeline_event, parent):
    start = timeline_event['s'] - self.start_time
    end = timeline_event['e'] - self.start_time
    if end > start:
        elapsed = end - start
        thread = timeline_event['t']
        name = self.event_name_lookup[timeline_event['n']]
        if 'main_thread' in self.cpu and thread == self.cpu['main_thread']:
            if elapsed > 50000:
                if start - self.interactive_start > 500000:
                    self.interactive.append([int(math.ceil(self.interactive_start / 1000.0)), int(math.floor(start / 1000.0))])
                self.interactive_start = end
                self.interactive_end = None
            else:
                self.interactive_end = end
        if 'js' in timeline_event:
            script = timeline_event['js']
            js_start = start / 1000.0
            js_end = end / 1000.0
            if self.scripts is None:
                self.scripts = {}
            if 'main_thread' not in self.scripts and 'main_thread' in self.cpu:
                self.scripts['main_thread'] = self.cpu['main_thread']
            if thread not in self.scripts:
                self.scripts[thread] = {}
            if script not in self.scripts[thread]:
                self.scripts[thread][script] = {}
            if name not in self.scripts[thread][script]:
                self.scripts[thread][script][name] = []
            existing_periods = set((tuple(period) for period in self.scripts[thread][script][name]))
            new_duration = True
            if existing_periods:
                for period in existing_periods:
                    if len(period) >= 2 and js_start >= period[0] and (js_end <= period[1]):
                        new_duration = False
                        break
            if new_duration:
                self.scripts[thread][script][name].append([js_start, js_end])
        slice_usecs = self.cpu['slice_usecs']
        first_slice = int(float(start) / float(slice_usecs))
        last_slice = int(float(end) / float(slice_usecs))
        for slice_number in xrange(first_slice, last_slice + 1):
            slice_start = slice_number * slice_usecs
            slice_end = slice_start + slice_usecs
            used_start = max(slice_start, start)
            used_end = min(slice_end, end)
            slice_elapsed = used_end - used_start
            self.AdjustTimelineSlice(thread, slice_number, name, parent, slice_elapsed)
        if 'c' in timeline_event:
            for child in timeline_event['c']:
                self.ProcessTimelineEvent(child, name)

def _walk_vdi_chain(session, vdi_uuid):
    while True:
        vdi_ref = session.call_xenapi('VDI.get_by_uuid', vdi_uuid)
        vdi_rec = session.call_xenapi('VDI.get_record', vdi_ref)
        yield vdi_rec
        parent_uuid = vdi_rec['sm_config'].get('vhd-parent')
        if parent_uuid:
            vdi_uuid = parent_uuid
        else:
            break

def _log(self, level, msg, args, exc_info=None, extra=None, context=None):
    if not extra:
        extra = {}
    if context:
        extra.update(_dictify_context(context))
    extra.update({'nova_version': version.string_with_vcs()})
    logging.Logger._log(self, level, msg, args, exc_info, extra)

def get_type(self, names):
    assert isinstance(names, list)
    for type_specifier in names:
        if type_specifier == 'int':
            typ = nodes.IntegerType('int', 4)
        elif type_specifier == 'void':
            typ = nodes.VoidType()
        elif type_specifier == 'char':
            typ = nodes.IntegerType('char', 1)
        elif type_specifier == 'float':
            typ = nodes.FloatingPointType('float')
        elif type_specifier == 'double':
            typ = nodes.FloatingPointType('double')
        elif type_specifier == 'unsigned':
            typ = nodes.IntegerType('int', 4)
        elif type_specifier == 'signed':
            typ = nodes.IntegerType('int', 4)
        elif type_specifier == 'short':
            typ = nodes.IntegerType('int', 2)
        elif type_specifier == 'long':
            typ = nodes.IntegerType('int', 8)
        else:
            raise NotImplementedError(str(type_specifier))
    print(typ)

def computeExpression(self, constraint_collection):
    source = self.getAssignSource()
    if source.willRaiseException(BaseException):
        return (source, 'new_raise', 'Keeper assignment raises.')
    constraint_collection.onVariableSet(assign_node=self)
    if self.variable.getReferenced().isWriteOnly():
        return (source, 'new_expression', '\nRemoved useless temporary keeper assignment.')
    return (self, None, None)

def import_jurisdiction(org_importer, jurisdiction):
    metadata = jurisdiction.get_metadata()
    metadata['_type'] = 'metadata'
    metadata['_id'] = jurisdiction.jurisdiction_id
    metadata['latest_update'] = datetime.datetime.utcnow()
    if 'name' not in metadata or 'parties' not in metadata:
        raise ValueError('Metadata must contain both name and parties.')
    db.metadata.save(metadata)
    org = {'_type': 'organization', 'classification': 'jurisdiction', 'parent_id': None, 'jurisdiction_id': jurisdiction.jurisdiction_id, 'name': metadata['name']}
    if 'other_names' in metadata:
        org['other_names'] = metadata['other_names']
    if 'parent_id' in metadata:
        org['parent_id'] = metadata['parent_id']
    org_importer.import_object(org)
    for party in metadata['parties']:
        org = {'_type': 'organization', 'classification': 'party', 'name': party['name'], 'parent_id': None}
        org_importer.import_object(org)

def _render_to_grayscale(self) -> np.ndarray:
    self.viewer.center_on_observer()
    self.viewer.display()
    raw_rgb = self.viewer.get_image()
    raw_rgb = np.moveaxis(raw_rgb, 0, 1)
    return np.dot(raw_rgb[..., :3], self.weights).clip(0, 255).astype(np.uint8)

def add_provisioning_network(self, task):
    LOG.debug('Binding flat network ports')
    node = task.node
    host_id = node.instance_info.get('nova_host_id')
    if not host_id:
        return
    ports = [p for p in task.ports if not p.portgroup_id]
    portgroups = task.portgroups
    client = neutron.get_client(task.context.auth_token)
    for port_like_obj in ports + portgroups:
        vif_port_id = port_like_obj.extra.get('vif_port_id') or port_like_obj.internal_info.get('tenant_vif_port_id')
        if not vif_port_id:
            continue
        body = {'port': {'binding:host_id': host_id}}
        try:
            client.update_port(vif_port_id, body)
        except neutron_exceptions.NeutronClientException as e:
            msg = _('Unable to set binding:host_id for neutron port %(port_id)s. Error: %(err)s') % {'port_id': vif_port_id, 'err': e}
            LOG.exception(msg)
            raise exception.NetworkError(msg)

